models = {'A': (0.95, 0.40), 'B': (0.75, 0.75)}
for name, (p, r) in models.items():
    print(name, 'precision', p, 'recall', r)
# prints: A precision 0.95 recall 0.4
# prints: B precision 0.75 recall 0.75

def precision(tp, fp):
    return tp / (tp + fp) if tp + fp else None

def recall(tp, fn):
    return tp / (tp + fn) if tp + fn else None

def f1(p, r):
    return 2 * p * r / (p + r) if p and r else 0.0

print(round(f1(0.5, 0.5), 3), round(f1(0.9, 0.1), 3))
# prints: 0.5 0.18

